	@Test
	void closeReturnsBeforeAnAdmittedCallbackAndDrainsAfterItsExit(@TempDir File directory) throws Exception {
		try (ObservedValues store = new ObservedValues(directory); var workers = Executors.newFixedThreadPool(2)) {
			ValueResolutionScope creator = store.openValueResolutionScope();
			List<Value> values = seed(store, creator, 1);
			long earlier = ((LmdbValue) values.getFirst()).getValueStoreRevision().getRevisionId();
			rotate(store, creator);
			CountDownLatch entered = new CountDownLatch(1);
			CountDownLatch released = new CountDownLatch(1);
			AtomicInteger closes = new AtomicInteger();
			AtomicInteger drains = new AtomicInteger();
			CloseableIteration<Value> source = new CloseableIteration<>() {
				@Override
				public boolean hasNext() {
					entered.countDown();
					try {
						assertTrue(released.await(10, TimeUnit.SECONDS), "The admitted callback must be released");
					} catch (InterruptedException failure) {
						Thread.currentThread().interrupt();
						throw new QueryInterruptedException(failure);
					}
					return false;
				}

				@Override
				public Value next() {
					throw new java.util.NoSuchElementException();
				}

				@Override
				public void close() {
					closes.incrementAndGet();
				}
			};
			try (var result = new RepositoryValueIteration<>(source, SailResultValueExtractor.VALUES, store, null, null,
					ignored -> drains.incrementAndGet())) {
				creator.close();
				var pulling = workers.submit(result::hasNext);
				assertTrue(entered.await(5, TimeUnit.SECONDS));
				try {
					workers.submit(result::close).get(5, TimeUnit.SECONDS);
					assertEquals(1, closes.get(), "Close must immediately cancel its source exactly once");
					assertEquals(0, drains.get(), "An admitted callback still owns the outward epoch horizon");
					assertFalse(store.unusedRevisionIds.contains(earlier));
				} finally {
					released.countDown();
				}
				assertFalse(pulling.get(5, TimeUnit.SECONDS));
				assertEquals(1, drains.get(), "The final admitted exit must drain once without a background task");
				assertTrue(store.unusedRevisionIds.contains(earlier));
			}
		}
	}

	@Test
	void concurrentCloseUnblocksAnActiveSourcePull(@TempDir File directory) throws Exception {
		try (ObservedValues store = new ObservedValues(directory); var workers = Executors.newFixedThreadPool(2)) {
			CountDownLatch entered = new CountDownLatch(1);
			CountDownLatch released = new CountDownLatch(1);
			CountDownLatch closed = new CountDownLatch(1);
			AtomicInteger closes = new AtomicInteger();
			CloseableIteration<Value> source = new CloseableIteration<>() {
				@Override
				public boolean hasNext() {
					entered.countDown();
					try {
						assertTrue(released.await(10, TimeUnit.SECONDS), "The fixture pull must be released by close");
					} catch (InterruptedException failure) {
						Thread.currentThread().interrupt();
						throw new QueryInterruptedException(failure);
					}
					return false;
				}

				@Override
				public Value next() {
					throw new java.util.NoSuchElementException();
				}

				@Override
				public void close() {
					closes.incrementAndGet();
					closed.countDown();
					released.countDown();
				}
			};
			try (var result = expose(store, source, null)) {
				var pulling = workers.submit(result::hasNext);
				assertTrue(entered.await(5, TimeUnit.SECONDS));
				var closing = workers.submit(result::close);
				try {
					assertTrue(closed.await(5, TimeUnit.SECONDS),
							"Concurrent close must reach source.close while source.hasNext is still blocked");
				} finally {
					// Fixture-only emergency release keeps a failed regression from hanging the worker pool.
					released.countDown();
				}
				assertFalse(pulling.get(5, TimeUnit.SECONDS));
				closing.get(5, TimeUnit.SECONDS);
				assertEquals(1, closes.get(), "The wrapper must claim source close exactly once");
			}
		}
	}

	@Test
	void sortingUsesOneCapturedIdentityRatherThanMutableIdReads(@TempDir File directory) throws Exception {
		try (ObservedValues store = new ObservedValues(directory);
				ValueResolutionScope creator = store.openValueResolutionScope()) {
			List<Value> values = seed(store, creator, 16);
			AtomicInteger mutableIdReads = new AtomicInteger();
			List<Value> observed = new ArrayList<>();
			for (Value value : values) {
				LmdbValue.InternalIdentity identity = ((LmdbValue) value).getInternalIdentity();
				observed.add(new LmdbBNode(identity.revision(), identity.id()) {
					@Override
					public long getInternalID() {
						mutableIdReads.incrementAndGet();
						return super.getInternalID();
					}
				});
			}
			Collections.reverse(observed);
			try (var result = exposeRoots(store, new CloseableIteratorIteration<>(List.of(observed).iterator()),
					null)) {
				while (result.hasNext()) {
					result.next();
				}
			}
			assertEquals(0, mutableIdReads.get(),
					"Sorting must use captured identity keys; concurrent ID reassignment must not change comparisons");
		}
	}

	@Test
	void dictionaryWavesReadRootsInKeyOrderWithoutReadingAnotherRow(@TempDir File directory) throws Exception {
		try (ObservedValues store = new ObservedValues(directory);
				ValueResolutionScope creator = store.openValueResolutionScope()) {
			List<Value> values = seed(store, creator, 257);
			Collections.reverse(values);
			List<List<Value>> rows = List.of(values.subList(0, 128), values.subList(128, 256),
					values.subList(256, 257));
			AtomicInteger pulls = new AtomicInteger();
			var source = new IterationWrapper<List<Value>>(new CloseableIteratorIteration<>(rows.iterator())) {
				@Override
				public List<Value> next() {
					pulls.incrementAndGet();
					return super.next();
				}
			};
			try (var result = exposeRoots(store, source, null)) {
				assertEquals(0, pulls.get(), "Constructing a result must not pull or initialize rows");
				assertSame(rows.getFirst(), result.next());
				assertEquals(1, pulls.get(), "Preparing a row must not execute callbacks needed for a later row");
				List<Long> firstWave = List.copyOf(store.decoded);
				assertEquals(128, firstWave.size(), "All distinct roots within the requested row must be batched");
				List<Long> sorted = new ArrayList<>(firstWave);
				sorted.sort(Long::compare);
				assertEquals(sorted, firstWave, "Native dictionary accesses must follow numeric key order");
				assertEquals(1, store.admissions.get());
				for (int row = 1; row < rows.size(); row++) {
					assertSame(rows.get(row), result.next(), "Materialization must preserve row identity and order");
					assertEquals(row + 1, pulls.get(), "Opaque source pulling must stay demand-driven for every row");
				}
				assertFalse(result.hasNext());
				assertEquals(1, store.admissions.get(), "Standalone batches must amortize one native reader");
			}
			assertTrue(store.readers.stream().allMatch(reader -> reader.isIdle() || reader.isClosed()));
		}
	}

	@Test
	void sourceClosingDuringNextCannotReleaseTheRowsOlderEpoch(@TempDir File directory) throws Exception {
		try (ObservedValues store = new ObservedValues(directory)) {
			ValueResolutionScope creator = store.openValueResolutionScope();
			List<Value> values = seed(store, creator, 2);
			long earlier = ((LmdbValue) values.getFirst()).getValueStoreRevision().getRevisionId();
			rotate(store, creator);
			var source = new IterationWrapper<List<Value>>(
					new CloseableIteratorIteration<>(List.of(values).iterator())) {
				@Override
				public List<Value> next() {
					List<Value> row = super.next();
					close();
					return row;
				}

				@Override
				protected void handleClose() {
					try {
						super.handleClose();
					} finally {
						creator.close();
					}
				}
			};
			try (var result = exposeRoots(store, source, null)) {
				assertSame(values, result.next());
				assertFalse(creator.isOpen(), "The source next must really close its inner owner before preparation");
				assertFalse(store.unusedRevisionIds.contains(earlier),
						"The outward owner retains the original horizon");
				for (Value value : values) {
					assertInstanceOf(ValueStoreRevision.Default.class, ((LmdbValue) value).getValueStoreRevision());
				}
				assertFalse(result.hasNext());
				assertTrue(store.unusedRevisionIds.contains(earlier),
						"Observed exhaustion releases the outward owner's horizon");
			}
		}
	}

	@Test
	void multipleResultsBorrowTheTransactionReaderAndBufferedRowsSurviveItsCompletion(@TempDir File directory)
			throws Exception {
		try (ObservedValues store = new ObservedValues(directory);
				ValueResolutionScope transaction = store.openValueResolutionScope()) {
			List<Value> values = seed(store, transaction, 4);
			List<Value> firstRow = values.subList(0, 2);
			List<Value> secondRow = values.subList(2, 4);
			try (var first = exposeRoots(store, new CloseableIteratorIteration<>(List.of(firstRow).iterator()),
					transaction);
					var second = exposeRoots(store, new CloseableIteratorIteration<>(List.of(secondRow).iterator()),
							transaction)) {
				assertTrue(first.hasNext());
				assertTrue(second.hasNext());
				assertEquals(1, store.admissions.get(),
						"Two results in one transaction must share its foreground reader");
				rotate(store, transaction);
				transaction.close();
				assertTrue(store.readers.stream().allMatch(reader -> reader.isIdle() || reader.isClosed()));
				assertSame(firstRow, first.next());
				assertSame(secondRow, second.next());
				assertFalse(first.hasNext());
				assertFalse(second.hasNext());
				assertEquals(1, store.admissions.get(),
						"Already ready buffered rows need no post-commit native reader");
			}
		}
	}

