	@Test
	void parkedBatchReaderRenewsAcrossDictionaryMapGrowth(@TempDir File directory) throws Exception {
		try (ObservedValues store = new ObservedValues(directory);
				ValueResolutionScope creator = store.openValueResolutionScope()) {
			List<Value> values = seed(store, creator, 257);
			AtomicInteger pulls = new AtomicInteger();
			var source = new IterationWrapper<Value>(new CloseableIteratorIteration<>(values.iterator())) {
				@Override
				public Value next() {
					if (pulls.incrementAndGet() == 129) {
						try (SailClosable activation = creator.activateForeground()) {
							store.startTransaction(true);
							long appended = store
									.storeValue(SimpleValueFactory.getInstance().createLiteral("x".repeat(2_000_000)));
							store.getLazyValue(appended);
							store.commit();
						} catch (IOException failure) {
							throw new SailException(failure);
						}
					}
					return super.next();
				}
			};
			try (var result = expose(store, source, null)) {
				for (Value expected : values) {
					assertSame(expected, result.next());
				}
				assertFalse(result.hasNext());
				assertEquals(1, store.admissions.get(), "Map renewal must keep the owned ordinary lease");
			}
		}
	}

	@Test
	void ascendingIdsMatchUnsignedLmdbVarintKeysAtEncodingBoundaries() {
		long[] ids = { 0, 127, 128, 240, 241, 2287, 2288, 67823, 67824, 16_777_215, 16_777_216,
				4_294_967_295L, 4_294_967_296L, Long.MAX_VALUE };
		byte[] previous = null;
		for (long id : ids) {
			ByteBuffer encoded = ByteBuffer.allocate(10);
			encoded.put((byte) 0); // Equal ID_KEY prefix, just like the dictionary's native keys.
			Varint.writeUnsigned(encoded, id);
			byte[] key = Arrays.copyOf(encoded.array(), encoded.position());
			if (previous != null) {
				assertTrue(Arrays.compareUnsigned(previous, key) < 0, "Numeric order must match unsigned LMDB keys");
			}
			previous = key;
		}
	}

	private static RepositoryValueIteration<Value> expose(ObservedValues store,
			CloseableIteration<? extends Value> source, ValueResolutionScope transaction) {
		return new RepositoryValueIteration<>(source, SailResultValueExtractor.VALUES, store, transaction, null,
				ignored -> {
				});
	}

	private static RepositoryValueIteration<List<Value>> exposeRoots(ObservedValues store,
			CloseableIteration<? extends List<Value>> source, ValueResolutionScope transaction) {
		return new RepositoryValueIteration<>(source, (row, roots) -> row.forEach(roots), store, transaction, null,
				ignored -> {
				});
	}

	private static List<Value> seed(ObservedValues store, ValueResolutionScope creator, int count) throws IOException {
		store.startTransaction(true);
		long[] ids = new long[count];
		for (int i = 0; i < count; i++) {
			ids[i] = store.storeValue(SimpleValueFactory.getInstance().createBNode("batch-value-" + i));
		}
		store.commit();
		store.clearCaches();
		List<Value> values = new ArrayList<>();
		try (SailClosable activation = creator.activateForeground()) {
			for (long id : ids) {
				values.add(store.getLazyValue(id));
			}
		}
		return values;
	}

	private static void rotate(ObservedValues store, ValueResolutionScope creator) throws IOException {
		try (SailClosable activation = creator.activateForeground()) {
			store.startTransaction(true);
			long id = store.storeValue(SimpleValueFactory.getInstance().createBNode("new-epoch"));
			store.getLazyValue(id);
			store.commit();
		}
	}

	private static final class ObservedValues extends ValueStore implements AutoCloseable {
		private final AtomicInteger admissions = new AtomicInteger();
		private final List<Long> decoded = new ArrayList<>();
		private final List<TxnManager.Txn> readers = new ArrayList<>();
		private long failureId = LmdbValue.UNKNOWN_ID;
		private Throwable failure;

		private ObservedValues(File directory) throws IOException {
			super(createDirectory(directory),
					new LmdbStoreConfig().setInlineLiterals(false).setValueDBSize(1_048_576).setAutoGrow(true));
		}

		private static File createDirectory(File directory) throws IOException {
			Files.createDirectories(directory.toPath());
			return directory;
		}

		@Override
		TxnManager.Txn tryRetainValueReader(ValueStoreRevision.Lazy revision) throws IOException {
			TxnManager.Txn reader = super.tryRetainValueReader(revision);
			if (reader != null) {
				admissions.incrementAndGet();
				readers.add(reader);
			}
			return reader;
		}

		@Override
		boolean resolveWithRetainedReader(TxnManager.Txn reader, long id, LmdbValue value,
				ValueStoreRevision.Lazy revision)
				throws IOException {
			decoded.add(id);
			if (id == failureId) {
				if (failure instanceof Error error) {
					throw error;
				}
				throw (RuntimeException) failure;
			}
			return super.resolveWithRetainedReader(reader, id, value, revision);
		}
	}
